import type { FlowState, MetricDescriptor, NumericStat, StreamState } from "./types";

type AnyRecord = Record<string, any>;

type NormalizedStreamInput = {
  time: number;
  stream: StreamState;
};

export type NormalizedMetricInput = {
  time: number;
  streamKey: string;
  flowKey: string;
  role: string;
  label: string;
  endpointSrc?: string;
  endpointDst?: string;
  metrics: Record<string, NumericStat>;
};

export function normalizeStreamsLine(line: string): NormalizedStreamInput[] {
  const parsed = JSON.parse(line) as AnyRecord;
  const time = Number(parsed.time ?? Date.now() / 1000);
  const streams = Array.isArray(parsed.streams) ? parsed.streams : [];
  return streams.map((entry) => normalizeStreamEntry(entry, time)).filter(Boolean) as NormalizedStreamInput[];
}

export function normalizeMetricsLine(line: string): NormalizedMetricInput[] {
  const parsed = JSON.parse(line) as AnyRecord;
  const time = Number(parsed.time ?? Date.now() / 1000);
  const metrics = Array.isArray(parsed.metrics) ? parsed.metrics : [];
  return metrics.map((entry) => normalizeMetricEntry(entry, time)).filter(Boolean) as NormalizedMetricInput[];
}

function normalizeStreamEntry(entry: AnyRecord, time: number): NormalizedStreamInput | undefined {
  const proto = String(entry?.proto ?? "OTHER");
  const raw = entry?.stream ?? {};
  const streamKey = String(raw.stream_key ?? entry.stream_key ?? "");
  if (!streamKey) return undefined;

  const rawFlows = Array.isArray(raw.flows) ? raw.flows : [];
  const flows: FlowState[] = rawFlows.length > 0
    ? rawFlows.map((flow: AnyRecord) => normalizeFlowState(flow, time))
    : [defaultFlow(streamKey, proto, raw, time)];

  const endpointA = raw.endpoint?.a;
  const endpointB = raw.endpoint?.b;
  const sessionDst = raw.session_dst;
  const label = proto === "RTP" && sessionDst
    ? `${proto} ${sessionDst}`
    : endpointA && endpointB
      ? `${proto} ${endpointA} <-> ${endpointB}`
      : streamKey;

  return {
    time,
    stream: {
      streamKey,
      kind: proto,
      proto,
      label,
      endpointA,
      endpointB,
      sessionDst,
      streamId: raw.streamid,
      active: true,
      lastSeen: Number(raw.last_seen ?? time),
      flowCount: flows.length,
      flowRoles: unique(flows.map((flow) => flow.role)),
      bitrate: {},
      sparkline: [],
      flows
    }
  };
}

function normalizeFlowState(flow: AnyRecord, time: number): FlowState {
  const role = String(flow.role ?? inferRoleFromKey(flow.flow_key) ?? "flow");
  const endpointSrc = flow.endpoint?.src;
  const endpointDst = flow.endpoint?.dst;
  return {
    flowKey: String(flow.flow_key),
    role,
    label: endpointSrc && endpointDst ? `${role}: ${endpointSrc} -> ${endpointDst}` : role,
    endpointSrc,
    endpointDst,
    lastSeen: Number(flow.last_seen ?? time),
    metrics: {}
  };
}

function defaultFlow(streamKey: string, proto: string, raw: AnyRecord, time: number): FlowState {
  const endpointSrc = raw.endpoint?.a;
  const endpointDst = raw.endpoint?.b;
  return {
    flowKey: `${streamKey}|flow=default`,
    role: "default",
    label: endpointSrc && endpointDst ? `${proto}: ${endpointSrc} -> ${endpointDst}` : "default",
    endpointSrc,
    endpointDst,
    lastSeen: Number(raw.last_seen ?? time),
    metrics: {}
  };
}

function normalizeMetricEntry(entry: AnyRecord, time: number): NormalizedMetricInput | undefined {
  const proto = String(entry?.proto ?? "OTHER");
  const streamKey = String(entry?.stream_key ?? "");
  if (!streamKey) return undefined;

  const flowKey = String(entry?.flow_key ?? `${streamKey}|flow=default`);
  const role = String(entry?.role ?? inferRoleFromKey(flowKey) ?? "default");
  const endpointSrc = entry?.endpoint?.src;
  const endpointDst = entry?.endpoint?.dst;
  const label = endpointSrc && endpointDst ? `${role}: ${endpointSrc} -> ${endpointDst}` : `${proto} ${role}`;

  return {
    time,
    streamKey,
    flowKey,
    role,
    label,
    endpointSrc,
    endpointDst,
    metrics: extractMetrics(entry)
  };
}

function extractMetrics(entry: AnyRecord): Record<string, NumericStat> {
  const metrics: Record<string, NumericStat> = {};
  for (const [key, value] of Object.entries(entry)) {
    if (ignoredMetricKeys.has(key)) continue;
    collectMetric(key, value, metrics);
  }
  return metrics;
}

const ignoredMetricKeys = new Set([
  "proto",
  "stream_key",
  "flow_key",
  "endpoint",
  "role",
  "payload_type",
  "ssrc"
]);

function collectMetric(prefix: string, value: unknown, output: Record<string, NumericStat>) {
  if (typeof value === "number" && Number.isFinite(value)) {
    output[prefix] = { value, avg: value, min: value, max: value };
    return;
  }

  if (!value || typeof value !== "object" || Array.isArray(value)) return;
  const record = value as AnyRecord;
  const stat = statFromObject(record);
  if (stat) {
    output[prefix] = stat;
    return;
  }

  for (const [childKey, childValue] of Object.entries(record)) {
    collectMetric(`${prefix}.${childKey}`, childValue, output);
  }
}

function statFromObject(record: AnyRecord): NumericStat | undefined {
  const stat: NumericStat = {};
  const value = firstNumber(record.value, record.bps, record.pps, record.seconds, record.total);
  if (value !== undefined) stat.value = value;
  if (isNumber(record.avg)) stat.avg = record.avg;
  if (isNumber(record.min)) stat.min = record.min;
  if (isNumber(record.max)) stat.max = record.max;
  if (isNumber(record.count)) stat.count = record.count;

  if (stat.avg === undefined && stat.value !== undefined) stat.avg = stat.value;
  if (stat.min === undefined && stat.value !== undefined) stat.min = stat.value;
  if (stat.max === undefined && stat.value !== undefined) stat.max = stat.value;

  return stat.value !== undefined || stat.avg !== undefined || stat.min !== undefined || stat.max !== undefined
    ? stat
    : undefined;
}

function firstNumber(...values: unknown[]) {
  return values.find(isNumber) as number | undefined;
}

function isNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

function inferRoleFromKey(flowKey?: string) {
  if (!flowKey) return undefined;
  const match = flowKey.match(/(?:^|\|)role=([^|]+)/);
  return match?.[1];
}

function unique(values: string[]) {
  return [...new Set(values)];
}

export function descriptorForMetric(key: string): MetricDescriptor {
  const rules: Array<Partial<MetricDescriptor> & { pattern: RegExp }> = [
    { pattern: /^bitrate$/, category: "primary", display: "range-line", priority: 10, unit: "bps" },
    { pattern: /^packet_rate$/, category: "primary", display: "range-line", priority: 20, unit: "pps" },
    { pattern: /^jitter$/, category: "primary", display: "range-line", priority: 30, unit: "s" },
    { pattern: /^rtt$/, category: "primary", display: "range-line", priority: 40, unit: "ms" },
    { pattern: /^bandwidth$/, category: "primary", display: "range-line", priority: 50, unit: "bps" },
    { pattern: /^packet_count\.total$/, category: "stat", display: "stat", priority: 100 },
    { pattern: /^seq_stats\./, category: "stat", display: "stat", priority: 110 },
    { pattern: /^control_type_count\./, category: "stat", display: "stat", priority: 120 }
  ];

  const match = rules.find((rule) => rule.pattern.test(key));
  return {
    key,
    label: labelForMetric(key),
    unit: match?.unit,
    category: match?.category ?? "secondary",
    display: match?.display ?? "range-line",
    priority: match?.priority ?? 1000
  };
}

function labelForMetric(key: string) {
  return key
    .split(".")
    .map((part) => part.replace(/_/g, " "))
    .join(" / ")
    .replace(/\b\w/g, (char) => char.toUpperCase());
}
