import { existsSync } from "node:fs";
import fastify from "fastify";
import fastifyStatic from "@fastify/static";
import { config } from "./config";
import { TailFile } from "./ingest/tailFile";
import { normalizeMetricsLine, normalizeStreamsLine } from "./normalizer";
import { registerRoutes } from "./api/routes";
import { StreamStore } from "./state/store";
import { SocketServer } from "./ws/socketServer";

async function main() {
  const app = fastify({ logger: true });
  const store = new StreamStore(config.historyWindowSec, config.staleAfterSec);

  await registerRoutes(app, store);

  if (existsSync(config.clientDist)) {
    await app.register(fastifyStatic, {
      root: config.clientDist,
      prefix: "/"
    });
    app.setNotFoundHandler((request, reply) => {
      if (request.raw.url?.startsWith("/api") || request.raw.url === "/ws") {
        return reply.code(404).send({ error: "not found" });
      }
      return reply.sendFile("index.html");
    });
  }

  const sockets = new SocketServer(app.server, store);
  sockets.start();

  const streamsTail = new TailFile({
    path: config.streamsLog,
    pollMs: config.pollMs,
    onLine: (line) => {
      try {
        for (const item of normalizeStreamsLine(line)) store.upsertStream(item.stream);
      } catch (error) {
        app.log.warn({ error }, "failed to parse streams log line");
      }
    },
    onError: (error) => app.log.warn({ error }, "failed to tail streams log")
  });

  const metricsTail = new TailFile({
    path: config.metricsLog,
    pollMs: config.pollMs,
    onLine: (line) => {
      try {
        for (const item of normalizeMetricsLine(line)) store.addMetric(item);
      } catch (error) {
        app.log.warn({ error }, "failed to parse metrics log line");
      }
    },
    onError: (error) => app.log.warn({ error }, "failed to tail metrics log")
  });

  streamsTail.start();
  metricsTail.start();

  const close = async () => {
    streamsTail.stop();
    metricsTail.stop();
    await app.close();
  };
  process.on("SIGINT", () => void close());
  process.on("SIGTERM", () => void close());

  await app.listen({ host: config.host, port: config.port });
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
