import { useMemo, useState } from "react";
import { DetailPane } from "./components/DetailPane";
import { StreamTable } from "./components/StreamTable";
import { useStreams } from "./hooks/useStreams";

export function App() {
  const [selectedStreamKey, setSelectedStreamKey] = useState<string | null>(null);
  const [query, setQuery] = useState("");
  const { streams, summary, selectedListItem, selectedStream, selectedMetrics, socketState } = useStreams(selectedStreamKey);

  const filteredStreams = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    if (!normalized) return streams;
    return streams.filter((stream) =>
      [stream.kind, stream.label, stream.streamKey, stream.flowRoles.join(" ")]
        .join(" ")
        .toLowerCase()
        .includes(normalized)
    );
  }, [streams, query]);

  const detailStream = selectedStream ?? (selectedListItem ? { ...selectedListItem, flows: [] } : null);

  return (
    <main className="app-shell">
      <section className="hero-panel">
        <div>
          <p className="eyebrow">Network Stream Monitor</p>
          <h1>Live stream topology and bitrate telemetry</h1>
        </div>
        <div className="summary-strip">
          <SummaryCard label="Streams" value={summary.totalStreams.toString()} />
          <SummaryCard label="Active" value={summary.activeStreams.toString()} />
          <SummaryCard label="Kinds" value={Object.keys(summary.byKind).length.toString()} />
          <SummaryCard label="Socket" value={socketState} />
        </div>
      </section>

      <section className="workspace">
        <aside className="list-pane">
          <div className="list-toolbar">
            <div>
              <h2>Streams</h2>
              <p>{filteredStreams.length} visible / {streams.length} total</p>
            </div>
            <input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Filter by kind, endpoint, role" />
          </div>
          <StreamTable streams={filteredStreams} selectedStreamKey={selectedStreamKey} onSelect={setSelectedStreamKey} />
        </aside>
        <DetailPane stream={detailStream} metrics={selectedMetrics} />
      </section>
    </main>
  );
}

function SummaryCard({ label, value }: { label: string; value: string }) {
  return <div className="summary-card"><span>{label}</span><strong>{value}</strong></div>;
}
