#!/usr/bin/env node
import { readFileSync, appendFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const root = resolve(new URL("..", import.meta.url).pathname);
const options = parseArgs(process.argv.slice(2));
const intervalMs = Number(options.intervalMs ?? process.env.DUMMY_INTERVAL_MS ?? 1000);
const once = Boolean(options.once);
const truncate = options.truncate !== false && process.env.DUMMY_TRUNCATE !== "0";
const streamsOut = resolve(root, String(options.streamsOut ?? process.env.STREAMS_LOG ?? "streams.log"));
const metricsOut = resolve(root, String(options.metricsOut ?? process.env.METRICS_LOG ?? "metrics.log"));
const eventsOut = resolve(root, String(options.eventsOut ?? process.env.EVENTS_LOG ?? "events.log"));
const eventEvery = Number(options.eventEvery ?? process.env.DUMMY_EVENT_EVERY ?? 3);

const sources = [
  {
    name: "rtp",
    streams: readJsonLines(resolve(root, "streams_rtp.log")),
    metrics: readJsonLines(resolve(root, "metrics_rtp.log"))
  },
  {
    name: "srt",
    streams: readJsonLines(resolve(root, "streams_srt.log")),
    metrics: readJsonLines(resolve(root, "metrics_srt.log"))
  }
].filter((source) => source.streams.length > 0 || source.metrics.length > 0);

if (sources.length === 0) {
  console.error("No sample source logs found. Expected streams_rtp.log/metrics_rtp.log and/or streams_srt.log/metrics_srt.log.");
  process.exit(1);
}

if (truncate) {
  writeFileSync(streamsOut, "");
  writeFileSync(metricsOut, "");
  writeFileSync(eventsOut, "");
}

let tick = 0;
const startedAt = Math.floor(Date.now() / 1000);

function emit() {
  const now = startedAt + tick;
  const streams = [];
  const metrics = [];

  for (const source of sources) {
    const streamFrame = source.streams[tick % source.streams.length];
    const metricFrame = source.metrics[tick % source.metrics.length];
    if (streamFrame?.streams) streams.push(...clone(streamFrame.streams));
    if (metricFrame?.metrics) metrics.push(...clone(metricFrame.metrics));
  }

  const streamSnapshot = touchTimes({ streams, time: now }, now);
  const metricSnapshot = touchTimes({ metrics, time: now }, now);

  appendFileSync(streamsOut, `${JSON.stringify(streamSnapshot)}\n`);
  appendFileSync(metricsOut, `${JSON.stringify(metricSnapshot)}\n`);

  let events = 0;
  if (eventEvery > 0 && tick % eventEvery === 0) {
    const event = makeEvent(streams, metrics, now, tick);
    if (event) {
      appendFileSync(eventsOut, `${JSON.stringify(event)}\n`);
      events = 1;
    }
  }

  console.log(`dummy tick=${tick} time=${now} streams=${streams.length} metrics=${metrics.length} events=${events}`);

  tick += 1;
}

emit();
if (!once) setInterval(emit, intervalMs);

function makeEvent(streams, metrics, now, tick) {
  const streamEntry = streams[tick % Math.max(streams.length, 1)];
  if (!streamEntry?.stream?.stream_key) return undefined;

  const stream = streamEntry.stream;
  const flow = Array.isArray(stream.flows) && stream.flows.length > 0
    ? stream.flows[tick % stream.flows.length]
    : undefined;
  const metric = flow?.flow_key
