    else if (arg === "--no-truncate") result.truncate = false;
    else if (arg.startsWith("--interval-ms=")) result.intervalMs = arg.slice("--interval-ms=".length);
    else if (arg.startsWith("--streams-out=")) result.streamsOut = arg.slice("--streams-out=".length);
    else if (arg.startsWith("--metrics-out=")) result.metricsOut = arg.slice("--metrics-out=".length);
    else if (arg.startsWith("--events-out=")) result.eventsOut = arg.slice("--events-out=".length);
    else if (arg.startsWith("--event-every=")) result.eventEvery = arg.slice("--event-every=".length);
  }
  return result;
}

