import { useEffect, useMemo, useState } from "react";
import { getEvents, getStream, getStreamMetrics, getStreams, getSummary } from "../api/client";
import type { EventLogItem, StreamListItem, StreamMetricsResponse, StreamState, Summary, WsMessage } from "../types/api";

export function useStreams(selectedStreamKey: string | null, onDefaultSelect?: (streamKey: string) => void) {
  const [streams, setStreams] = useState<StreamListItem[]>([]);
  const [summary, setSummary] = useState<Summary>({ totalStreams: 0, activeStreams: 0, byKind: {} });
  const [selectedStream, setSelectedStream] = useState<StreamState | null>(null);
  const [selectedMetrics, setSelectedMetrics] = useState<StreamMetricsResponse | null>(null);
  const [socketState, setSocketState] = useState("connecting");
  const [events, setEvents] = useState<EventLogItem[]>([]);

  useEffect(() => {
    void Promise.all([getStreams(), getSummary(), getEvents({ limit: 100 })]).then(([streamItems, summaryValue, eventItems]) => {
      setStreams(streamItems);
      setSummary(summaryValue);
      setEvents(eventItems);
      if (!selectedStreamKey && streamItems.length > 0) onDefaultSelect?.(streamItems[0].streamKey);
    });
  }, []);

  useEffect(() => {
    if (!selectedStreamKey) {
      setSelectedStream(null);
      setSelectedMetrics(null);
      return;
    }
    void Promise.all([getStream(selectedStreamKey), getStreamMetrics(selectedStreamKey)]).then(([stream, metrics]) => {
      setSelectedStream(stream);
      setSelectedMetrics(metrics);
    });
  }, [selectedStreamKey]);

  useEffect(() => {
    const protocol = window.location.protocol === "https:" ? "wss" : "ws";
    const socket = new WebSocket(`${protocol}://${window.location.host}/ws`);
    socket.onopen = () => setSocketState("connected");
    socket.onclose = () => setSocketState("closed");
