import { useEffect, useRef, useState } from "react";
import type { FlowListItem, StreamListItem } from "../types/api";
import { Sparkline } from "./Sparkline";
import { formatBitrate, formatRelativeTime } from "./format";

type StreamTableProps = {
  streams: StreamListItem[];
  selectedStreamKey: string | null;
  selectedFlowKey: string | null;
  onSelectStream: (streamKey: string) => void;
  onSelectFlow: (streamKey: string, flowKey: string) => void;
};

export function StreamTable({ streams, selectedStreamKey, selectedFlowKey, onSelectStream, onSelectFlow }: StreamTableProps) {
  const [expanded, setExpanded] = useState<Set<string>>(() => new Set());
  const initializedExpansion = useRef(false);

  useEffect(() => {
    if (initializedExpansion.current || streams.length === 0) return;
    initializedExpansion.current = true;
    setExpanded(new Set(streams.filter(isExpandable).map((stream) => stream.streamKey)));
  }, [streams]);

  const selectStream = (stream: StreamListItem) => {
    onSelectStream(stream.streamKey);
    if (isExpandable(stream)) {
      setExpanded((current) => new Set(current).add(stream.streamKey));
    }
  };

  const toggleStream = (streamKey: string) => {
    setExpanded((current) => {
      const next = new Set(current);
      if (next.has(streamKey)) next.delete(streamKey);
      else next.add(streamKey);
      return next;
    });
  };

  return (
    <div className="stream-table">
      {streams.map((stream) => {
        const expandable = isExpandable(stream);
        const opened = expanded.has(stream.streamKey);
        return (
          <div className="stream-tree" key={stream.streamKey}>
            <button
              className={`stream-row ${stream.streamKey === selectedStreamKey && !selectedFlowKey ? "selected" : ""}`}
              onClick={() => selectStream(stream)}
            >
              <span className={`tree-toggle ${expandable ? "expandable" : ""} ${opened ? "open" : ""}`} onClick={(event) => { event.stopPropagation(); if (expandable) toggleStream(stream.streamKey); }}>
                {expandable ? "›" : ""}
              </span>
              <span className={`status-dot ${stream.active ? "active" : "stale"}`} />
              <span className="stream-main">
                <span className="stream-title">
                  <strong>{stream.kind}</strong>
                  <span>{stream.label}</span>
                </span>
                <span className="stream-subtitle">
                  {stream.flowCount} flow{stream.flowCount === 1 ? "" : "s"}
                  {stream.flowRoles.length > 0 ? ` / ${stream.flowRoles.join(", ")}` : ""}
                  {" / "}{formatRelativeTime(stream.lastSeen)}
                </span>
              </span>
              <span className="row-right">
                <span className="stream-rate">{formatBitrate(stream.bitrate.value ?? stream.bitrate.avg)}</span>
                <Sparkline values={stream.sparkline} width={96} height={24} />
              </span>
            </button>
            {expandable && (
              <div className={`flow-branch ${opened ? "open" : "closed"}`}>
                <div className="flow-branch-inner">
                  {stream.flows.map((flow) => (
                    <FlowRow
                      key={flow.flowKey}
                      flow={flow}
                      selected={flow.flowKey === selectedFlowKey}
                      onSelect={() => onSelectFlow(stream.streamKey, flow.flowKey)}
                    />
                  ))}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

function FlowRow({ flow, selected, onSelect }: { flow: FlowListItem; selected: boolean; onSelect: () => void }) {
  return (
    <button className={`flow-list-row ${selected ? "selected" : ""}`} onClick={onSelect}>
      <span className="tree-elbow" />
      <span className="flow-main">
        <span className="flow-title"><strong>{flow.role}</strong><span>{flow.label}</span></span>
        <span className="flow-subtitle">{flow.endpointSrc ?? "-"} {"->"} {flow.endpointDst ?? "-"}</span>
      </span>
      <span className="row-right">
        <span className="stream-rate">{formatBitrate(flow.bitrate.value ?? flow.bitrate.avg)}</span>
        <Sparkline values={flow.sparkline} width={96} height={24} />
      </span>
    </button>
  );
}

function isExpandable(stream: StreamListItem) {
  return stream.flows.length > 1 || stream.flows.some((flow) => flow.role !== "default");
}

