function StreamSummaryChart({ stream, scaleMax }: { stream: StreamListItem; scaleMax: number }) {
  const width = 96;
  const height = 24;
  const topHeight = 16;
  const barHeight = 5;
  const barY = 18;
  const totalValues = normalizeSeries(stream.sparkline);
  const flowSeries = stream.flows.map((flow) => ({
    flowKey: flow.flowKey,
    role: flow.role,
    values: normalizeSeries(flow.sparkline)
  }));
  const count = totalValues.length;

  if (count === 0) return <div className="sparkline-empty" style={{ width, height }} />;

  const linePoints = totalValues.map((value, index) => {
    const x = count === 1 ? width : (index / (count - 1)) * width;
    const y = topHeight - ((Math.max(0, Math.min(scaleMax, value)) / scaleMax) * (topHeight - 4)) - 2;
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(" ");

  const barWidth = width / count;

  return (
    <svg className="stream-summary-chart" width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
      <polyline points={linePoints} fill="none" stroke={TOTAL_COLOR} strokeWidth="2" strokeLinejoin="round" strokeLinecap="round" />
      {totalValues.map((total, index) => {
        if (total <= 0) return null;
