import { useEffect, useMemo, useRef, useState } from "react";
import type { FlowListItem, StreamListItem } from "../types/api";
import { Sparkline } from "./Sparkline";
import { formatBitrate, formatRelativeTime } from "./format";

type StreamTableProps = {
  streams: StreamListItem[];
  selectedStreamKey: string | null;
  selectedFlowKey: string | null;
  onSelectStream: (streamKey: string) => void;
  onSelectFlow: (streamKey: string, flowKey: string) => void;
};

const TOTAL_COLOR = "#66d9ef";
const FLOW_ROLE_COLORS: Record<string, string> = {
  media: "#8bd17c",
  fec_row: "#d6b66f",
  fec_col: "#d98b7f",
  control: "#7fa7d9",
  mixed: "#c58bd6",
  default: "#8fa4bc"
};
const FLOW_ROLE_LINE_COLORS: Record<string, string> = {
  media: "#a5df99",
  fec_row: "#e1c98a",
  fec_col: "#e5a494",
  control: "#9abbe3",
  mixed: "#d2a6e5",
  default: "#b5c0cf"
};

export function StreamTable({ streams, selectedStreamKey, selectedFlowKey, onSelectStream, onSelectFlow }: StreamTableProps) {
  const [expanded, setExpanded] = useState<Set<string>>(() => new Set());
  const initializedExpansion = useRef(false);

  useEffect(() => {
    if (initializedExpansion.current || streams.length === 0) return;
    initializedExpansion.current = true;
    setExpanded(new Set(streams.filter(isExpandable).map((stream) => stream.streamKey)));
  }, [streams]);

  const selectStream = (stream: StreamListItem) => {
    onSelectStream(stream.streamKey);
    if (isExpandable(stream)) {
      setExpanded((current) => new Set(current).add(stream.streamKey));
    }
  };

  const toggleStream = (streamKey: string) => {
    setExpanded((current) => {
      const next = new Set(current);
      if (next.has(streamKey)) next.delete(streamKey);
      else next.add(streamKey);
      return next;
    });
  };

  return (
    <div className="stream-table">
      {streams.map((stream) => {
        const expandable = isExpandable(stream);
        const opened = expanded.has(stream.streamKey);
        const streamBitrate = stream.bitrate.value ?? stream.bitrate.avg ?? 0;
        const streamScaleMax = Math.max(...stream.sparkline, streamBitrate, 1);

        return (
          <div className="stream-tree" key={stream.streamKey}>
            <button
              className={`stream-row ${stream.streamKey === selectedStreamKey && !selectedFlowKey ? "selected" : ""}`}
              onClick={() => selectStream(stream)}
            >
              <span className={`tree-toggle ${expandable ? "expandable" : ""} ${opened ? "open" : ""}`} onClick={(event) => { event.stopPropagation(); if (expandable) toggleStream(stream.streamKey); }}>
                {expandable ? "›" : ""}
              </span>
              <span className={`status-dot ${stream.active ? "active" : "stale"}`} />
              <span className="stream-main">
                <span className="stream-title">
                  <strong>{stream.kind}</strong>
                  <span>{stream.label}</span>
                </span>
                <span className="stream-subtitle">
                  {stream.flowCount} flow{stream.flowCount === 1 ? "" : "s"}
                  {stream.flowRoles.length > 0 ? ` / ${stream.flowRoles.join(", ")}` : ""}
                  {" / "}{formatRelativeTime(stream.lastSeen)}
                </span>
              </span>
              <span className="row-right stream-row-right">
                <span className="stream-rate">{formatBitrate(streamBitrate)}</span>
                <StreamSummaryChart stream={stream} scaleMax={streamScaleMax} />
              </span>
            </button>
            {expandable && (
              <div className={`flow-branch ${opened ? "open" : "closed"}`}>
                <div className="flow-branch-inner">
                  {stream.flows.map((flow) => (
                    <FlowRow
                      key={flow.flowKey}
                      flow={flow}
                      scaleMax={streamScaleMax}
                      selected={flow.flowKey === selectedFlowKey}
                      onSelect={() => onSelectFlow(stream.streamKey, flow.flowKey)}
                    />
                  ))}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

function FlowRow({ flow, scaleMax, selected, onSelect }: { flow: FlowListItem; scaleMax: number; selected: boolean; onSelect: () => void }) {
  const flowBitrate = flow.bitrate.value ?? flow.bitrate.avg ?? 0;
  const color = flowLineColor(flow.role);

  return (
    <button className={`flow-list-row ${selected ? "selected" : ""}`} onClick={onSelect}>
      <span className="tree-elbow" />
      <span className="flow-main">
        <span className="flow-title"><strong>{flow.role}</strong><span>{flow.label}</span></span>
        <span className="flow-subtitle">{flow.endpointSrc ?? "-"} {"->"} {flow.endpointDst ?? "-"}</span>
      </span>
      <span className="row-right flow-row-right">
        <span className="stream-rate">{formatBitrate(flowBitrate)}</span>
        <Sparkline values={flow.sparkline} width={96} height={24} minValue={0} maxValue={scaleMax} color={color} />
      </span>
    </button>
  );
}

function StreamSummaryChart({ stream, scaleMax }: { stream: StreamListItem; scaleMax: number }) {
  const width = 96;
  const height = 24;
  const topHeight = 16;
  const barHeight = 5;
  const barY = 18;
  const totalValues = normalizeSeries(stream.sparkline);
  const flowSeries = stream.flows.map((flow) => ({
    flowKey: flow.flowKey,
    role: flow.role,
    values: normalizeSeries(flow.sparkline)
  }));
  const count = totalValues.length;

  if (count === 0) return <div className="sparkline-empty" style={{ width, height }} />;

  const linePoints = totalValues.map((value, index) => {
    const x = count === 1 ? width : (index / (count - 1)) * width;
    const y = topHeight - ((Math.max(0, Math.min(scaleMax, value)) / scaleMax) * (topHeight - 4)) - 2;
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(" ");

  const barWidth = width / count;

  return (
    <svg className="stream-summary-chart" width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
      <polyline points={linePoints} fill="none" stroke={TOTAL_COLOR} strokeWidth="2" strokeLinejoin="round" strokeLinecap="round" />
      {totalValues.map((total, index) => {
        if (total <= 0) return null;
        const x = index * barWidth;
        let offset = 0;
        return flowSeries.map((series) => {
          const value = Math.max(0, series.values[index] ?? 0);
          const ratio = Math.max(0, Math.min(1, value / total));
          const segmentWidth = barWidth * ratio;
          if (segmentWidth <= 0.25) return null;
          const rect = (
            <rect
              key={`${series.flowKey}:${index}`}
              x={x + offset}
              y={barY}
              width={segmentWidth}
              height={barHeight}
              rx={0.8}
              fill={flowBarColor(series.role)}
              opacity={0.95}
            />
          );
          offset += segmentWidth;
          return rect;
        });
      })}
    </svg>
  );
}

function normalizeSeries(values: number[]) {
  if (values.length >= 60) return values.slice(-60);
  return [...Array(Math.max(0, 60 - values.length)).fill(0), ...values];
}

function flowBarColor(role: string) {
  return FLOW_ROLE_COLORS[role] ?? FLOW_ROLE_COLORS.default;
}

function flowLineColor(role: string) {
  return FLOW_ROLE_LINE_COLORS[role] ?? FLOW_ROLE_LINE_COLORS.default;
}

function isExpandable(stream: StreamListItem) {
  return stream.flows.length > 1 || stream.flows.some((flow) => flow.role !== "default");
}

