function normalizeSeries(values: number[]) {
  if (values.length >= 60) return values.slice(-60);
  return [...Array(Math.max(0, 60 - values.length)).fill(0), ...values];
}

function alignSeries(values: number[], count: number) {
  const tail = values.slice(-count);
  return [...Array(Math.max(0, count - tail.length)).fill(undefined), ...tail];
}

function flowBarColor(role: string) {
  return FLOW_ROLE_COLORS[role] ?? FLOW_ROLE_COLORS.default;
}

function flowLineColor(role: string) {
  return FLOW_ROLE_LINE_COLORS[role] ?? FLOW_ROLE_LINE_COLORS.default;
}

function isExpandable(stream: StreamListItem) {
  return stream.flows.length > 1 || stream.flows.some((flow) => flow.role !== "default");
}

