.hero-panel { display: flex; align-items: end; justify-content: space-between; gap: 24px; padding: 28px; border: 1px solid var(--line); border-radius: 28px; background: linear-gradient(135deg, rgba(14,29,43,.9), rgba(37,28,18,.72)); box-shadow: 0 24px 80px rgba(0,0,0,.28); }
.eyebrow { margin: 0 0 8px; color: var(--accent); text-transform: uppercase; letter-spacing: .16em; font-size: 12px; }
h1, h2, h3, p { margin-top: 0; }
h1 { margin-bottom: 0; font-size: clamp(30px, 5vw, 58px); line-height: .96; letter-spacing: -.05em; max-width: 740px; }
.summary-strip { display: grid; grid-template-columns: repeat(4, minmax(86px, 1fr)); gap: 10px; min-width: min(520px, 100%); }
.summary-card, .stat-card { border: 1px solid var(--line); border-radius: 18px; padding: 14px; background: rgba(255,255,255,.045); }
.summary-card span, .stat-card span { display: block; color: var(--muted); font-size: 12px; }
.summary-card strong, .stat-card strong { display: block; margin-top: 5px; font-size: 20px; }
.workspace { display: grid; grid-template-columns: minmax(420px, 42vw) 1fr; gap: 18px; margin-top: 18px; align-items: start; }
.list-pane, .detail-pane { border: 1px solid var(--line); border-radius: 28px; background: var(--panel); backdrop-filter: blur(18px); min-height: 640px; overflow: hidden; }
.list-toolbar { display: grid; grid-template-columns: 1fr; gap: 12px; padding: 20px; border-bottom: 1px solid var(--line); }
.list-toolbar h2 { margin-bottom: 4px; }
.list-toolbar p { margin-bottom: 0; color: var(--muted); }
.list-toolbar input { width: 100%; border: 1px solid var(--line); background: rgba(0,0,0,.22); color: #e8eef5; border-radius: 14px; padding: 12px 14px; outline: none; }
.stream-table { max-height: calc(100vh - 250px); overflow: auto; padding: 8px; }
.stream-row { width: 100%; display: grid; grid-template-columns: 12px minmax(0, 1fr) 110px 130px; align-items: center; gap: 12px; border: 1px solid transparent; border-radius: 18px; padding: 12px; color: inherit; background: transparent; text-align: left; cursor: pointer; }
.stream-row:hover, .stream-row.selected { background: rgba(102,217,239,.08); border-color: rgba(102,217,239,.28); }
.status-dot { width: 9px; height: 9px; border-radius: 50%; background: #8fa4bc; box-shadow: 0 0 18px currentColor; }
.status-dot.active { background: #56f39a; color: #56f39a; }
.status-dot.stale { background: #f7786b; color: #f7786b; }
.stream-main { min-width: 0; }
.stream-title, .stream-subtitle { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.stream-title strong { color: var(--accent-2); margin-right: 8px; }
.stream-subtitle { margin-top: 4px; color: var(--muted); font-size: 12px; }
.stream-rate { font-variant-numeric: tabular-nums; color: #f3f7fb; }
.sparkline { color: var(--accent); opacity: .9; }
.sparkline-empty { width: 120px; height: 30px; border-radius: 10px; background: rgba(255,255,255,.04); }
.detail-pane { padding: 20px; overflow: auto; max-height: calc(100vh - 188px); }
.empty-state { display: grid; place-items: center; color: var(--muted); }
.detail-header { border-bottom: 1px solid var(--line); padding-bottom: 18px; margin-bottom: 18px; }
.detail-header h2 { margin: 10px 0 6px; font-size: 28px; letter-spacing: -.03em; overflow-wrap: anywhere; }
.detail-header p { color: var(--muted); margin-bottom: 0; }
