  if (!flowMetrics || flowMetrics.length === 0) return null;

  return (
    <section className={compact ? "metric-group compact" : "metric-group"}>
      <h3>{descriptor.label}</h3>
      <div className="chart-stack">
        {flowMetrics.map(({ flow, metric }) => (
          <MetricChart key={`${flow.flowKey}:${descriptor.key}`} title={flow.label} metric={metric} height={compact ? 130 : 170} color={colorForMetric(descriptor.key)} />
