import { useEffect, useMemo, useState } from "react";
import type { StreamState } from "./types/api";
import { DetailPane } from "./components/DetailPane";
import { EventLog } from "./components/EventLog";
import { formatRelativeTime } from "./components/format";
import { StreamTable } from "./components/StreamTable";
import { useStreams } from "./hooks/useStreams";

export function App() {
  const [selectedStreamKey, setSelectedStreamKey] = useState<string | null>(null);
  const [selectedFlowKey, setSelectedFlowKey] = useState<string | null>(null);
  const [query, setQuery] = useState("");
  const [now, setNow] = useState(() => new Date());
  const [eventsHeight, setEventsHeight] = useState(240);
  const [rightColumnHeight, setRightColumnHeight] = useState(640);

  useEffect(() => {
    const timer = window.setInterval(() => setNow(new Date()), 1000);
    return () => window.clearInterval(timer);
  }, []);
  const { streams, summary, selectedListItem, selectedStream, selectedMetrics, socketState, events } = useStreams(selectedStreamKey, setSelectedStreamKey);

  const filteredStreams = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    if (!normalized) return streams;
    return streams.filter((stream) =>
      [stream.kind, stream.label, stream.streamKey, stream.flowRoles.join(" ")]
        .join(" ")
        .toLowerCase()
        .includes(normalized)
    );
  }, [streams, query]);

  const detailStream: StreamState | null = selectedStream ?? (selectedListItem ? { ...selectedListItem, flows: [] } : null);

  const startResizeEvents = (event: React.PointerEvent<HTMLDivElement>) => {
    const startY = event.clientY;
    const startHeight = eventsHeight;
    const columnHeight = event.currentTarget.parentElement?.getBoundingClientRect().height ?? rightColumnHeight;
    setRightColumnHeight(columnHeight);
    event.currentTarget.setPointerCapture(event.pointerId);

    const onMove = (moveEvent: PointerEvent) => {
      const maxHeight = Math.max(220, columnHeight - 72);
      const next = Math.min(maxHeight, Math.max(220, startHeight - (moveEvent.clientY - startY)));
      setEventsHeight(next);
    };
    const onUp = () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
  };

  return (
    <main className="app-shell">
      <section className="hero-panel compact-header">
        <div className="status-strip">
          <span className="live-badge">LIVE</span>
          <div>
            <strong>Realtime stream telemetry</strong>
            <span>Now {now.toLocaleTimeString()} / Updated {summary.updatedAt ? formatRelativeTime(summary.updatedAt) : "waiting"} / 5m history</span>
          </div>
        </div>
        <div className="summary-strip">
          <SummaryCard label="Streams" value={summary.totalStreams.toString()} />
          <SummaryCard label="Active" value={summary.activeStreams.toString()} />
          <SummaryCard label="Kinds" value={Object.keys(summary.byKind).length.toString()} />
          <SummaryCard label="Socket" value={socketState} />
        </div>
      </section>

      <section className="workspace">
        <aside className="list-pane">
          <div className="list-toolbar">
            <div>
              <h2>Streams</h2>
              <p>{filteredStreams.length} visible / {streams.length} total</p>
            </div>
            <label className="search-box">
              <span aria-hidden="true">⌕</span>
              <input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Filter by kind, endpoint, role" />
            </label>
          </div>
          <StreamTable
            streams={filteredStreams}
            selectedStreamKey={selectedStreamKey}
            selectedFlowKey={selectedFlowKey}
            onSelectStream={(streamKey) => {
              setSelectedStreamKey(streamKey);
              setSelectedFlowKey(null);
            }}
            onSelectFlow={(streamKey, flowKey) => {
              setSelectedStreamKey(streamKey);
              setSelectedFlowKey(flowKey);
            }}
          />
        </aside>
        <section className="right-column" style={{ gridTemplateRows: `minmax(0, 1fr) 8px ${eventsHeight}px` }}>
          <DetailPane stream={detailStream} metrics={selectedMetrics} selectedFlowKey={selectedFlowKey} />
          <div className="pane-splitter" role="separator" aria-orientation="horizontal" onPointerDown={startResizeEvents} />
          <EventLog events={events} selectedStreamKey={selectedStreamKey} selectedFlowKey={selectedFlowKey} />
        </section>
      </section>
    </main>
  );
}

function SummaryCard({ label, value }: { label: string; value: string }) {
  return <div className="summary-card"><span>{label}</span><strong>{value}</strong></div>;
}

