import { useState } from "react";
import type { EventLogItem } from "../types/api";

type EventLogProps = {
  events: EventLogItem[];
  selectedStreamKey: string | null;
  selectedFlowKey: string | null;
  onMinimize: () => void;
  onMaximize: () => void;
  isMinimized: boolean;
  isMaximized: boolean;
};

export function EventLog({ events, selectedStreamKey, selectedFlowKey, onMinimize, onMaximize, isMinimized, isMaximized }: EventLogProps) {
  const [tab, setTab] = useState<"all" | "selected">("selected");
  const [query, setQuery] = useState("");
  const scopedEvents = tab === "all" ? events : events.filter((event) => {
    if (selectedFlowKey) return event.flowKey === selectedFlowKey || event.streamKey === selectedStreamKey;
    if (selectedStreamKey) return event.streamKey === selectedStreamKey;
    return false;
  });
  const normalizedQuery = query.trim().toLowerCase();
  const visibleEvents = normalizedQuery
    ? scopedEvents.filter((event) => eventMatches(event, normalizedQuery))
    : scopedEvents;

  return (
    <section className={`events-card ${isMinimized ? "minimized" : ""}`}>
      <div className="events-header">
        <h3>Events</h3>
        <div className="events-actions">
          <div className="events-size-controls">
            <button type="button" className={isMinimized ? "active" : ""} onClick={onMinimize} aria-pressed={isMinimized} title="Minimize log pane">▁</button>
            <button type="button" className={isMaximized ? "active" : ""} onClick={onMaximize} aria-pressed={isMaximized} title="Maximize log pane">▔</button>
          </div>
          <label className="event-search">
            <span aria-hidden="true">⌕</span>
            <input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search events" />
          </label>
          <div className="events-tabs">
            <button className={tab === "all" ? "active" : ""} onClick={() => setTab("all")}>All events</button>
            <button className={tab === "selected" ? "active" : ""} onClick={() => setTab("selected")}>Selected</button>
          </div>
        </div>
      </div>
      {!isMinimized && (
        <div className="events-list">
          {visibleEvents.length === 0 ? (
            <div className="events-empty">No events</div>
          ) : visibleEvents.map((event) => <EventRow key={event.id} event={event} />)}
        </div>
      )}
    </section>
  );
}

function EventRow({ event }: { event: EventLogItem }) {
  return (
    <div className={`event-row ${event.level}`}>
      <span className="event-time">{formatEventTime(event.time)}</span>
      <span className="event-level">{event.level}</span>
      <span className="event-target">{event.targetLabel ?? event.proto ?? event.scope}</span>
      <span className="event-message">{event.message}</span>
    </div>
  );
}

function formatEventTime(epochSec: number) {
  const date = new Date(epochSec * 1000);
  const pad = (value: number) => String(value).padStart(2, "0");
  return `${date.getFullYear()}/${pad(date.getMonth() + 1)}/${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
}

function eventMatches(event: EventLogItem, query: string) {
  return [
    formatEventTime(event.time),
    event.level,
    event.type,
    event.scope,
    event.proto,
    event.streamKey,
    event.flowKey,
    event.targetLabel,
    event.message
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase()
    .includes(query);
}
