import { formatBitrate, formatNumber, formatRelativeTime } from "./format";
import { MetricChart } from "./MetricChart";

type DetailPaneProps = {
  stream: StreamState | null;
  metrics: StreamMetricsResponse | null;
  selectedFlowKey?: string | null;
  onMinimizeWidth: () => void;
  onRestoreWidth: () => void;
  onMaximizeWidth: () => void;
  isWidthMinimized: boolean;
  isWidthRestored: boolean;
  isWidthMaximized: boolean;
  showWidthControls: boolean;
};

type DetailMode = "standard" | "graph";

const FLOW_ROLE_ACCENTS: Record<string, string> = {
  media: "#7fd4c7",
  fec_row: "#62b7c3",
  fec_col: "#6e97c7",
  control: "#5f7fb9",
  mixed: "#6fa7d4",
  default: "#7f98b5"
};

export function DetailPane({
  stream,
  metrics,
  selectedFlowKey,
  onMinimizeWidth,
  onRestoreWidth,
  onMaximizeWidth,
  isWidthMinimized,
  isWidthRestored,
  isWidthMaximized,
  showWidthControls
}: DetailPaneProps) {
  const [mode, setMode] = useState<DetailMode>("standard");

  if (!stream) {
    return <aside className="detail-pane empty-state">Select a stream to inspect bitrate and flow metrics.</aside>;
  }

  const descriptors = metrics?.descriptors ?? [];
  const visibleFlows = selectedFlowKey ? stream.flows.filter((flow) => flow.flowKey === selectedFlowKey) : stream.flows;
  const visibleMetrics = metrics && selectedFlowKey
    ? { ...metrics, flows: metrics.flows.filter((flow) => flow.flowKey === selectedFlowKey) }
    : metrics;
  const primary = descriptors.filter((descriptor) => descriptor.category === "primary");
  const secondary = descriptors.filter((descriptor) => descriptor.category === "secondary");
  const stats = descriptors.filter((descriptor) => descriptor.category === "stat");

  return (
