  useEffect(() => {
    const maxHeight = Math.max(MINIMIZED_EVENTS_HEIGHT, rightColumnHeight - 8);
    setEventsHeight((current) => Math.min(Math.max(current, MINIMIZED_EVENTS_HEIGHT), maxHeight));
    setEventsRestoreHeight((current) => Math.min(Math.max(current, MINIMIZED_EVENTS_HEIGHT), maxHeight));
  }, [rightColumnHeight]);

  useEffect(() => {
    const maxRightWidth = Math.max(MIN_RIGHT_WIDTH, workspaceWidth - 8);
    setRightPaneWidth((current) => Math.min(Math.max(current, MIN_RIGHT_WIDTH), maxRightWidth));
    setRightPaneRestoreWidth((current) => Math.min(Math.max(current, MIN_RIGHT_WIDTH), maxRightWidth));
  }, [workspaceWidth]);

  const { streams, summary, selectedListItem, selectedStream, selectedMetrics, socketState, events } = useStreams(selectedStreamKey, setSelectedStreamKey);

  const filteredStreams = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    if (!normalized) return streams;
    return streams.filter((stream) =>
      [stream.kind, stream.label, stream.streamKey, stream.flowRoles.join(" ")]
        .join(" ")
        .toLowerCase()
        .includes(normalized)
    );
  }, [streams, query]);

  const detailStream: StreamState | null = selectedStream ?? (selectedListItem ? { ...selectedListItem, flows: [] } : null);

  const eventsMaxHeight = Math.max(MINIMIZED_EVENTS_HEIGHT, rightColumnHeight - 8);
  const eventsMinimized = eventsHeight <= MINIMIZED_EVENTS_HEIGHT;
  const eventsMaximized = eventsMaxHeight > MINIMIZED_EVENTS_HEIGHT && eventsHeight >= eventsMaxHeight;
  const eventsRestored = !eventsMinimized && !eventsMaximized;
  const rightColumnRows = eventsMaximized
    ? `0px 8px minmax(0, 1fr)`
    : `minmax(0, 1fr) 8px ${Math.max(MINIMIZED_EVENTS_HEIGHT, eventsHeight)}px`;

  const wideLayout = workspaceWidth > 1100;
  const maxRightWidth = Math.max(MIN_RIGHT_WIDTH, workspaceWidth - 8);
  const rightPaneMaximized = wideLayout && rightPaneWidth >= maxRightWidth;
  const rightPaneMinimized = !wideLayout || rightPaneWidth <= MIN_RIGHT_WIDTH;
  const rightPaneRestored = wideLayout && !rightPaneMaximized && !rightPaneMinimized;
  const workspaceColumns = wideLayout
    ? `minmax(0, 1fr) 8px ${Math.min(maxRightWidth, Math.max(MIN_RIGHT_WIDTH, rightPaneWidth))}px`
    : undefined;

  const startResizeEvents = (event: React.PointerEvent<HTMLDivElement>) => {
    const startY = event.clientY;
    const startHeight = eventsHeight;
    const columnHeight = event.currentTarget.parentElement?.getBoundingClientRect().height ?? rightColumnHeight;
    setRightColumnHeight(columnHeight);
