        const streamBitrate = stream.bitrate.value ?? stream.bitrate.avg ?? 0;
        const streamScaleMax = Math.max(...stream.sparkline, streamBitrate, 1);

        return (
          <div className="stream-tree" key={stream.streamKey}>
            <button
              className={`stream-row ${stream.streamKey === selectedStreamKey && !selectedFlowKey ? "selected" : ""}`}
