function OverviewStats({ stats }: { stats: StreamListItem["overview"] }) {
  return (
    <span className="overview-stats" aria-label="Overview counters">
      <span><small>Gap</small><strong>{formatCount(stats.gap)}</strong></span>
      <span><small>Dup</small><strong>{formatCount(stats.dup)}</strong></span>
      <span><small>Re</small><strong>{formatCount(stats.reorder)}</strong></span>
      <span><small>Ev</small><strong>{formatCount(stats.events)}</strong></span>
