import type { FlowState, MetricDescriptor, NumericStat, StreamState } from "./types";

type AnyRecord = Record<string, any>;

type NormalizedStreamInput = {
  time: number;
  stream: StreamState;
};

export type NormalizedMetricInput = {
  time: number;
  streamKey: string;
  flowKey: string;
  role: string;
  label: string;
  endpointSrc?: string;
  endpointDst?: string;
  metrics: Record<string, NumericStat>;
};

export function normalizeStreamsLine(line: string): NormalizedStreamInput[] {
  const parsed = JSON.parse(line) as AnyRecord;
  const time = Number(parsed.time ?? Date.now() / 1000);
  const streams = Array.isArray(parsed.streams) ? parsed.streams : [];
  return streams.map((entry) => normalizeStreamEntry(entry, time)).filter(Boolean) as NormalizedStreamInput[];
}

export function normalizeMetricsLine(line: string): NormalizedMetricInput[] {
  const parsed = JSON.parse(line) as AnyRecord;
  const time = Number(parsed.time ?? Date.now() / 1000);
  const metrics = Array.isArray(parsed.metrics) ? parsed.metrics : [];
  return metrics.map((entry) => normalizeMetricEntry(entry, time)).filter(Boolean) as NormalizedMetricInput[];
}

function normalizeStreamEntry(entry: AnyRecord, time: number): NormalizedStreamInput | undefined {
  const proto = String(entry?.proto ?? "OTHER");
  const raw = entry?.stream ?? {};
  const streamKey = String(raw.stream_key ?? entry.stream_key ?? "");
  if (!streamKey) return undefined;

  const rawFlows = Array.isArray(raw.flows) ? raw.flows : [];
  const flows: FlowState[] = rawFlows.length > 0
    ? rawFlows.map((flow: AnyRecord) => normalizeFlowState(flow, time))
    : [defaultFlow(streamKey, proto, raw, time)];

  const endpointA = raw.endpoint?.a;
  const endpointB = raw.endpoint?.b;
  const sessionDst = raw.session_dst;
  const label = proto === "RTP" && sessionDst
    ? `${proto} ${sessionDst}`
    : endpointA && endpointB
      ? `${proto} ${endpointA} <-> ${endpointB}`
      : streamKey;

  return {
    time,
    stream: {
      streamKey,
      kind: proto,
      proto,
      label,
      endpointA,
      endpointB,
      sessionDst,
      streamId: raw.streamid,
      active: true,
      lastSeen: Number(raw.last_seen ?? time),
      flowCount: flows.length,
      flowRoles: unique(flows.map((flow) => flow.role)),
      bitrate: {},
      sparkline: [],
      flows
    }
  };
}

function normalizeFlowState(flow: AnyRecord, time: number): FlowState {
  const role = String(flow.role ?? inferRoleFromKey(flow.flow_key) ?? "flow");
  const endpointSrc = flow.endpoint?.src;
  const endpointDst = flow.endpoint?.dst;
  return {
    flowKey: String(flow.flow_key),
    role,
    label: endpointSrc && endpointDst ? `${role}: ${endpointSrc} → ${endpointDst}` : role,
    endpointSrc,
    endpointDst,
    lastSeen: Number(flow.last_seen ?? time),
    metrics: {}
  };
}

function defaultFlow(streamKey: string, proto: string, raw: AnyRecord, time: number): FlowState {
  const endpointSrc = raw.endpoint?.a;
  const endpointDst = raw.endpoint?.b;
  return {
    flowKey: `${streamKey}|flow=default`,
    role: "default",
    label: endpointSrc && endpointDst ? `${proto}: ${endpointSrc} → ${endpointDst}` : "default",
    endpointSrc,
    endpointDst,
    lastSeen: Number(raw.last_seen ?? time),
    metrics: {}
  };
}

function normalizeMetricEntry(entry: AnyRecord, time: number): NormalizedMetricInput | undefined {
  const proto = String(entry?.proto ?? "OTHER");
  const streamKey = String(entry?.stream_key ?? "");
  if (!streamKey) return undefined;

  const flowKey = String(entry?.flow_key ?? `${streamKey}|flow=default`);
  const role = String(entry?.role ?? inferRoleFromKey(flowKey) ?? "default");
