import { existsSync } from "node:fs";
import path from "node:path";

const rootDir = path.resolve(__dirname, "../..");
const argv = parseArgs(process.argv.slice(2));

const logDir = path.resolve(
  rootDir,
  String(argv.logDir ?? process.env.LOG_DIR ?? ".")
);
const streamsLogFile = resolveLogFileName(
  argv.logStreams ?? process.env.LOG_STREAMS ?? process.env.STREAMS_LOG_FILE ?? process.env.STREAMS_LOG ?? "streams.log",
  "streams"
);
const metricsLogFile = resolveLogFileName(
  argv.logMetrics ?? process.env.LOG_METRICS ?? process.env.METRICS_LOG_FILE ?? process.env.METRICS_LOG ?? "metrics.log",
  "metrics"
);
const eventsLogFile = resolveLogFileName(
  argv.logEvents ?? process.env.LOG_EVENTS ?? process.env.EVENTS_LOG_FILE ?? process.env.EVENTS_LOG ?? "events.log",
  "events"
);

export const config = {
  host: String(argv.host ?? process.env.HOST ?? "0.0.0.0"),
  port: Number(argv.port ?? process.env.PORT ?? 3000),
  rootDir,
  logDir,
  streamsLogFile,
  metricsLogFile,
  eventsLogFile,
  streamsLog: path.resolve(logDir, streamsLogFile),
  metricsLog: path.resolve(logDir, metricsLogFile),
  eventsLog: path.resolve(logDir, eventsLogFile),
  historyWindowSec: Number(process.env.HISTORY_WINDOW_SEC ?? 300),
  staleAfterSec: Number(process.env.STALE_AFTER_SEC ?? 5),
  pollMs: Number(process.env.LOG_POLL_MS ?? 500),
  maxEvents: Number(process.env.MAX_EVENTS ?? 1000),
  clientDist: path.resolve(rootDir, "client/dist")
};

export function ensureLogFilesExist() {
  const required = [
    { label: "streams", path: config.streamsLog },
    { label: "metrics", path: config.metricsLog },
    { label: "events", path: config.eventsLog }
  ];

  for (const file of required) {
    if (!existsSync(file.path)) {
      throw new Error(`missing ${file.label} log file: ${file.path}`);
    }
  }
}

function resolveLogFileName(value: unknown, label: string) {
  const fileName = String(value ?? "").trim();
  if (!fileName) throw new Error(`missing ${label} log file name`);
  if (path.basename(fileName) !== fileName) {
    throw new Error(`${label} log file must be a file name, not a path: ${fileName}`);
  }
  return fileName;
}

function parseArgs(args: string[]) {
  const parsed: Record<string, string> = {};
  for (const arg of args) {
    if (!arg.startsWith("--")) continue;
    const [rawKey, ...rest] = arg.slice(2).split("=");
    const value = rest.join("=");
    if (!rawKey || !value) continue;
    if (rawKey === "log-dir") parsed.logDir = value;
    else if (rawKey === "log-streams") parsed.logStreams = value;
    else if (rawKey === "log-metrics") parsed.logMetrics = value;
    else if (rawKey === "log-events") parsed.logEvents = value;
    else if (rawKey === "host") parsed.host = value;
    else if (rawKey === "port") parsed.port = value;
  }
  return parsed;
}

