export type NumericStat = {
  value?: number;
  avg?: number;
  min?: number;
  max?: number;
  count?: number;
};

export type MetricPoint = NumericStat & {
  time: number;
};

export type FlowMetricPoint = {
  time: number;
  metrics: Record<string, NumericStat>;
};

export type FlowState = {
  flowKey: string;
  role: string;
  label: string;
  endpointSrc?: string;
  endpointDst?: string;
  lastSeen: number;
  metrics: Record<string, NumericStat>;
};

export type StreamState = {
  streamKey: string;
  kind: string;
  proto: string;
  label: string;
  endpointA?: string;
  endpointB?: string;
  sessionDst?: string;
  streamId?: string;
  active: boolean;
  lastSeen: number;
  flowCount: number;
  flowRoles: string[];
  bitrate: NumericStat;
  sparkline: number[];
  flows: FlowState[];
};

export type FlowListItem = {
  flowKey: string;
  role: string;
  label: string;
  endpointSrc?: string;
  endpointDst?: string;
  lastSeen: number;
  bitrate: NumericStat;
  sparkline: number[];
  overview: OverviewStats;
};

export type StreamListItem = Omit<StreamState, "flows"> & {
  overview: OverviewStats;
  flows: FlowListItem[];
};

export type OverviewStats = {
  gap: number;
  dup: number;
  reorder: number;
  events: number;
};

export type MetricDescriptor = {
  key: string;
  label: string;
  unit?: string;
  category: "primary" | "secondary" | "stat";
  display: "range-line" | "line" | "stat";
  priority: number;
};

export type TimeSeriesMetric = {
  key: string;
  label: string;
  unit?: string;
  points: MetricPoint[];
};

export type FlowMetricsResponse = {
  flowKey: string;
  role: string;
  label: string;
  endpointSrc?: string;
  endpointDst?: string;
  metrics: Record<string, TimeSeriesMetric>;
};

export type StreamMetricsResponse = {
  streamKey: string;
  windowSec: number;
  streamBitrate: TimeSeriesMetric;
  flows: FlowMetricsResponse[];
  descriptors: MetricDescriptor[];
};

export type EventLogItem = {
  id: string;
